function ATTR = attr_catalog(region)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%ATTR_CATALOG Return SAGE catchment-attribute labels by region.
%
% SYNOPSIS:
%   ATTR = attr_catalog(region)
%
%   region      character/string scalar with region identifier
%                'CAMELS_AU'  Australia CAMELS attributes
%                'CAMELS_AR'  Argentina GRDC-Caravan attributes
%                'CAMELS_AT'  Austria CAMELS attributes
%                'CAMELS_BR'  Brazil CAMELS attributes
%                'CAMELS_CA'  Canada CAMELS-SPAT attributes
%                'CAMELS_BE'  Belgium GRDC-Caravan attributes
%                'CAMELS_CL'  Chile CAMELS attributes
%                'CAMELS_COL' Colombia CAMELS attributes
%                'CAMELS_CH'  Switzerland CAMELS attributes
%                'CAMELS_CZ'  Czechia CAMELS attributes
%                'CAMELS_DE'  Germany CAMELS attributes
%                'CAMELS_DK'  Denmark CAMELS attributes
%                'CAMELS_ES'  Spain CAMELS attributes
%                'BULL_ES'    Spain BULL attributes
%                'CAMELS_EE'  Estonia GRDC-Caravan attributes
%                'CAMELS_GB'  Great Britain CAMELS attributes
%                'CAMELS_FI'  Finland CAMELS attributes
%                'CAMELS_FR'  France CAMELS attributes
%                'CAMELS_IND' India CAMELS attributes
%                'CAMELS_IS'  Iceland LamaH-Ice attributes
%                'CAMELS_IE'  Ireland GRDC-Caravan attributes
%                'CAMELS_JM'  Jamaica GRDC-Caravan attributes
%                'CAMELS_JP'  Japan MERV-Jp HydroATLAS attributes
%                'CAMELSH_KR'  South Korea CAMELSH-KR attributes
%                'CAMELS_IL'  Israel LamaH-IL attributes
%                'CAMELS_LUX' Luxembourg CAMELS attributes
%                'CAMELS_MX'  Mexico Caravan-HYSETS attributes
%                'CAMELS_NZ'  New Zealand CAMELS attributes
%                'CAMELS_NO'  Norway GRDC-Caravan attributes
%                'CAMELS_NA'  Namibia GRDC-Caravan attributes
%                'CAMELS_PE'  Peru CAMELS attributes
%                'CAMELS_PL'  Poland CAMELS attributes
%                'CAMELS_PR'  Puerto Rico GRDC-Caravan attributes
%                'CAMELS_SE'  Sweden CAMELS attributes
%                'CAMELS_US'  United States CAMELS attributes
%                'CAMELSH_US' United States CAMELSH hourly attributes
%                'MACH_US'    United States MACH attributes
%                'CAMELS_ZA'  South Africa GRDC-Caravan attributes
%   ATTR        OUTPUT: structure with regional catchment-attribute catalog
%    .region     normalized region code
%    .labels     1xr cell array with GUI/display labels
%    .names      1xr cell array with raw attribute variable names
%
% NOTES:
%   Attribute order should mirror the corresponding regional
%   read_attr_* function. For CAMELS_GB, the order follows read_attr_GB:
%   topo -> climatic -> hydrologic -> hydrogeology -> soil -> landcover
%   -> human influence -> hydrometry, excluding gauge_id and gauge_name.
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% © Written by Jasper A. Vrugt, Dec. 2025 / updated Apr. 2026             %
% University of California, Irvine                                        %
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

    if nargin < 1 ...
            || isempty(region)
        region = 'CAMELS_FR';
    end
    
    region = region_helpers('code',region);

    % Catalogs are static during a GUI session. Cache the completed result
    % so large catalogs (notably Canada and South Korea) are not rebuilt
    % every time a control refreshes.
    persistent catalogCache catalogVersion
    expectedCatalogVersion = 11; % increment when schema/display labels change
    if isempty(catalogVersion) || catalogVersion ~= expectedCatalogVersion
        catalogCache = struct();
        catalogVersion = expectedCatalogVersion;
    end
    cacheKey = matlab.lang.makeValidName(region);
    if ~isempty(catalogCache) ...
            && isfield(catalogCache,cacheKey)
        ATTR = catalogCache.(cacheKey);
        return
    end

    % CAMELS_US and CAMELSH_US are distinct datasets, so their catalogs
    % cannot both dispatch through the generic "US" suffix. Other
    % CAMELSH regions retain the normal country-suffix convention.
    if strcmp(region,'CAMELSH_US')
        funcName = 'local_ush_catalog';
    elseif strcmp(region,'MACH_US')
        funcName = 'local_mach_catalog';
    elseif strcmp(region,'BULL_ES')
        funcName = 'local_bull_catalog';
    else
        if startsWith(region,'CAMELSH_')
            suffix = extractAfter(region,'CAMELSH_');
        else
            suffix = extractAfter(region,'CAMELS_');
        end
        funcName = sprintf('local_%s_catalog',lower(suffix));
    end
    catalogFcn = str2func(funcName);
    ATTR = catalogFcn();
    % Apply one Unicode unit style to every regional display catalog.
    % Raw variable names remain unchanged for attribute-file matching.
    ATTR.labels = local_typographic_units(ATTR.labels);
    ATTR.region = region;
    if isempty(catalogCache)
        catalogCache = struct();
    end
    catalogCache.(cacheKey) = ATTR;

end


% ===============================================
function labels = local_typographic_units(labels)
% ===============================================
% Use Unicode unit typography because uitable/uilabel text does not use a
% TeX interpreter. This changes display labels only, never field names.

    originalSize = size(labels);
    txt = string(labels);

    % Temperature and angular units.
    txt = replace(txt,'(C)','(°C)');
    txt = replace(txt,'(degrees)','(°)');

    % Area and volume forms found in source catalogs.
    txt = regexprep(txt,'\<km(\^)?2\>','km²');
    txt = regexprep(txt,'\<m(\^)?2\>','m²');
    txt = regexprep(txt,'\<m(\^)?3\>','m³');

    % Plain-text annual/monthly inverse units.
    txt = replace(txt,'year-1','year⁻¹');
    txt = replace(txt,'month-1','month⁻¹');
    txt = replace(txt,'day-1','day⁻¹');
    txt = replace(txt,'hour-1','hour⁻¹');
    txt = replace(txt,'event-1','event⁻¹');

    % Slash-form compound units. Restrict replacements to known unit
    % denominators so descriptive ratios such as precipitation/PET remain.
    txt = replace(txt,'/km²',' km⁻²');
    txt = replace(txt,'/m²',' m⁻²');
    txt = replace(txt,'/km',' km⁻¹');
    txt = replace(txt,'/ha',' ha⁻¹');
    txt = replace(txt,'/year',' year⁻¹');
    txt = replace(txt,'/month',' month⁻¹');
    txt = replace(txt,'/day',' d⁻¹');
    txt = replace(txt,'/hour',' h⁻¹');
    txt = replace(txt,'/event',' event⁻¹');
    txt = replace(txt,'/s',' s⁻¹');

    % Remaining caret exponents used by radiation, density, conductivity,
    % discharge, and other source-provided units.
    txt = replace(txt,'^-1','⁻¹');
    txt = replace(txt,'^-2','⁻²');
    txt = replace(txt,'^-3','⁻³');
    txt = replace(txt,'^2','²');
    txt = replace(txt,'^3','³');

    labels = reshape(cellstr(txt),originalSize);
end

% ================================
function ATTR = local_ca_catalog()
% ================================
% CAMELS-SPAT Canada catalog.
%
% The catalog exposes all 1,178 source attributes in attributes-lumped.csv,
% plus station latitude, station longitude, catchment area, and a synthetic
% total forest fraction. Hydrologic signatures remain available for manual
% inspection, but the 35 default predictors use only location, topography,
% climate, geology, soil, and land-cover information. The seven categorical
% seasonal-timing fields are listed but disabled because SAGE requires
% numeric predictor attributes.

    labels = { ...
        '[1] Gauge latitude (°)'; ...
        '[2] Gauge longitude (°)'; ...
        '[3] Catchment area (km²)'; ...
        '[4] Total forest fraction (-)'; ...
