        828 984 1032 936 1128 1152 840 1080 4 766 765 763 764 768 769
        ];

end

% ===============================================
function labels = local_ca_display_labels(labels,names)
% ===============================================
% Make the very large Canadian attribute catalog easier to read.
%
% Source-dataset suffixes (for example, "— SOILGRIDS", "— RDRS", and
% "— MERIT Hydro") are omitted from the GUI. The source information is
% useful metadata, but repeating it in every table row makes the attribute
% names unnecessarily long. Soil and geology variables are additionally
% translated from source variable names into readable descriptions.

    for i = 1:numel(labels)
        label = labels{i};

        % Remove repeated source/product annotations at the end.
        label = regexprep(label,'\s+—\s+.*$','');

        % Use the same compact unit notation as the other regional catalogs.
        unit_old = { ...
            '(mm year-1)', '(mm month-1)', '(mm day^-1)', '(mm d^-1)', ...
            '(days year^-1)', '(W m^-2)', '(m s^-1)', '(kg kg^-1)', ...
            '(g kg^-1)', '(dg kg^-1)', '(cg cm^-3)', '(cm^3 dm^-3)', ...
            '(cm hr^-1)', '(kPa kPa^-1)', '(m^2 m^-2)', '(km^2)', ...
            '(m^2)', '(million~m^3)', '(km^-1)', '(C)', '(degrees)'};
        unit_new = { ...
            '(mm/year)', '(mm/month)', '(mm/d)', '(mm/d)', ...
            '(days/year)', '(W/m²)', '(m/s)', '(kg/kg)', ...
            '(g/kg)', '(dg/kg)', '(cg/cm³)', '(cm³/dm³)', ...
            '(cm/hour)', '(-)', '(m²/m²)', '(km²)', ...
            '(m²)', '(million m³)', '(1/km)', '(°C)', '(°)'};
        for u = 1:numel(unit_old)
            label = strrep(label,unit_old{u},unit_new{u});
        end

        % Write out the two record-length fields rather than displaying
        % source variable names and redundant count units.
        if strcmp(names{i},'num_years_rdrs')
            label = regexprep(label,'num_years_rdrs\s*\(years\)', ...
                'Number of years used for climate statistics');
        elseif strcmp(names{i},'num_years_hyd')
            label = regexprep(label,'num_years_hyd\s*\(years\)', ...
                'Number of years used for hydrologic signatures');
        end

        % Preserve the index and any existing physical unit.
        tok = regexp(label,'^(\[\d+\])\s+([^:]+):\s*(.*)$', ...
            'tokens','once');
        if isempty(tok)
            labels{i} = label;
            continue
        end

        idx      = tok{1};
        category = strtrim(tok{2});
        body     = strtrim(tok{3});
        unitTok  = regexp(body,'\s+(\([^)]*\))$','tokens','once');
        unit = '';
        if ~isempty(unitTok)
            unit = [' ' unitTok{1}];
        end

        if strcmpi(category,'Soil') || strcmpi(category,'Geology')
            body = local_ca_attribute_description(names{i});
            labels{i} = sprintf('%s %s: %s%s',idx,category,body,unit);
        else
            bodyPretty = local_ca_general_description(names{i});
            if isempty(bodyPretty)
                labels{i} = label;
            else
                labels{i} = sprintf('%s %s: %s%s', ...
                    idx,category,bodyPretty,unit);
            end
        end
    end
end

% ==================================================
function txt = local_ca_general_description(name)
% ==================================================
% Translate repeated climate and hydrology variable-name patterns into
% natural-language display labels. Return an empty character vector when
% no reliable translation is available, so the existing label is retained.

    txt = '';

    monthNames = { ...
        'January','February','March','April','May','June', ...
        'July','August','September','October','November','December'};

    % Human-readable names for variables that occur in monthly groups.
    key = { ...
        'pet1','PR0','tdavg','tdmin','tdmax','FB','FI','P0','HU','HR', ...
        'UVC','phi','aridity1','fracsnow1','prec','pet2','srad', ...
        'tavg','tmax','tmin','vapr','wind','aridity2','fracsnow2', ...
        'daily_streamflow'};
    val = { ...
        'potential evapotranspiration','precipitation', ...
        'mean daily temperature','minimum daily temperature', ...
        'maximum daily temperature','downward shortwave radiation', ...
        'downward longwave radiation','surface air pressure', ...
        'specific humidity','relative humidity','wind speed', ...
        'wind direction','aridity','snow fraction','precipitation', ...
        'potential evapotranspiration','solar radiation', ...
        'mean temperature','maximum temperature','minimum temperature', ...
        'water-vapor pressure','wind speed','aridity','snow fraction', ...
        'streamflow'};

    % Pattern: variable_mean_month_05 or variable_std_month_05.
    tok = regexp(name,'^(.+)_(mean|std)_month_(\d{2})$', ...
        'tokens','once');
    if ~isempty(tok)
        base = tok{1};
        stat = tok{2};
        m = str2double(tok{3});
        k = find(strcmp(key,base),1);
        if ~isempty(k) && isfinite(m) && m >= 1 && m <= 12
            if strcmp(stat,'mean')
                statText = 'mean';
            else
                statText = 'standard deviation';
            end
            txt = sprintf('%s %s %s',val{k},monthNames{m},statText);
            return
        end
    end

    % Event signatures: high_temp_dur_mean, low_prec_timing, etc.
    tok = regexp(name, ...
        '^(low_temp|high_temp|low_prec|high_prec|no_flow|low_flow|high_flow)_' ...
        + "(freq|dur_mean|dur_median|dur_skew|dur_kurtosis|timing)$", ...
        'tokens','once');
    if ~isempty(tok)
        eventKey = tok{1};
        statKey  = tok{2};

        eventOld = { ...
            'low_temp','high_temp','low_prec','high_prec', ...
            'no_flow','low_flow','high_flow'};
        eventNew = { ...
            'low temperature','high temperature','low precipitation', ...
            'high precipitation','no-flow','low-flow','high-flow'};
        statOld = { ...
            'freq','dur_mean','dur_median','dur_skew','dur_kurtosis', ...
            'timing'};
        statNew = { ...
            'frequency','mean duration','median duration', ...
            'duration skewness','duration kurtosis','timing'};

        e = find(strcmp(eventOld,eventKey),1);
        s = find(strcmp(statOld,statKey),1);
        if ~isempty(e) && ~isempty(s)
            txt = sprintf('%s %s',eventNew{e},statNew{s});
            return
        end
    end

    % Streamflow percentiles: q1_mean, q1_std, ..., q99_std.
    tok = regexp(name,'^q(\d+)_(mean|std)$','tokens','once');
    if ~isempty(tok)
        p = str2double(tok{1});
        if strcmp(tok{2},'mean')
            statText = 'mean';
        else
            statText = 'standard deviation';
        end
        txt = sprintf('%s-percentile streamflow %s', ...
            local_ca_ordinal_number(p),statText);
        return
    end

    % Monthly leaf-area index.
    tok = regexp(name,'^lai_(mean|std)_month_(\d{2})$', ...
        'tokens','once');
    if ~isempty(tok)
        m = str2double(tok{2});
        if isfinite(m) && m >= 1 && m <= 12
            if strcmp(tok{1},'mean')
                statText = 'mean';
            else
                statText = 'standard deviation';
            end
            txt = sprintf('leaf-area index %s %s', ...
                monthNames{m},statText);
            return
        end
    end

    % Forest height by reference year.
    tok = regexp(name,'^forest_height_(\d{4})_(min|mean|max|std)$', ...
        'tokens','once');
    if ~isempty(tok)
        statOld = {'min','mean','max','std'};
        statNew = {'minimum','mean','maximum','standard deviation'};
        s = find(strcmp(statOld,tok{2}),1);
        txt = sprintf('forest height %s, %s',statNew{s},tok{1});
        return
    end

    % GLCLU, MODIS, and LGRIP land-cover fractions.
    tok = regexp(name,'^lc([123])_(.+)_fraction$','tokens','once');
    if ~isempty(tok)
        classText = strrep(tok{2},'_',' ');
        classText = strrep(classText,'built up','built-up');
        classText = strrep(classText,'semi arid','semi-arid');
        classText = strrep(classText,'no data','no-data');
        classText = strrep(classText,'non cropland','non-cropland');
        classText = strrep(classText,'rainfed','rain-fed');
        classText = strrep(classText,'cropland natural mosaic', ...
            'cropland–natural vegetation mosaic');
        classText = strrep(classText,'permanent snow ice', ...
            'permanent snow and ice');
        classText = strrep(classText,'urban and built up', ...
            'urban and built-up area');
        classText = strrep(classText,'wetland sparse vegetation', ...
            'wetland with sparse vegetation');
        classText = strrep(classText,'wetland dense short vegetation', ...
            'wetland with dense short vegetation');
        classText = strrep(classText,'wetland open tree cover', ...
            'wetland with open tree cover');
        classText = strrep(classText,'wetland dense tree cover', ...
            'wetland with dense tree cover');
        classText = strrep(classText,'wetland tree cover gain', ...
            'wetland tree-cover gain');
        classText = strrep(classText,'wetland tree cover loss', ...
            'wetland tree-cover loss');
        classText(1) = upper(classText(1));
        txt = sprintf('%s fraction',classText);
        return
    end

    % Topographic and drainage-network descriptors.
    topoOld = { ...
        'centroid_lat','centroid_lon','basin_area','gauge_lat','gauge_lon', ...
        'elev_min','elev_mean','elev_max','elev_std', ...
        'slope_min','slope_mean','slope_max','slope_std', ...
        'aspect_min','aspect_mean','aspect_max','aspect_std', ...
        'stream_length_min','stream_length_mean','stream_length_max', ...
        'stream_length_std','segment_length_total','stream_order_max', ...
        'stream_density','elongation_ratio'};
    topoNew = { ...
        'catchment-centroid latitude','catchment-centroid longitude', ...
        'catchment area','gauge latitude','gauge longitude', ...
        'minimum elevation','mean elevation','maximum elevation', ...
        'elevation standard deviation', ...
        'minimum slope','mean slope','maximum slope', ...
        'slope standard deviation', ...
        'minimum aspect','mean aspect','maximum aspect', ...
        'aspect standard deviation', ...
        'minimum stream-segment length','mean stream-segment length', ...
        'maximum stream-segment length','stream-segment length standard deviation', ...
        'total stream-segment length','maximum stream order', ...
        'stream density','catchment elongation ratio'};
    k = find(strcmp(topoOld,name),1);
    if ~isempty(k)
        txt = topoNew{k};
        return
    end

    % Open-water and reservoir descriptors.
    waterOld = { ...
        'open_water_number','known_reservoirs', ...
        'open_water_area_min','open_water_area_mean','open_water_area_max', ...
        'open_water_area_std','open_water_area_total', ...
        'open_water_volume_min','open_water_volume_mean','open_water_volume_max', ...
        'open_water_volume_std','open_water_volume_total', ...
        'reservoir_area_min','reservoir_area_mean','reservoir_area_max', ...
        'reservoir_area_std','reservoir_area_total', ...
        'reservoir_volume_min','reservoir_volume_mean','reservoir_volume_max', ...
        'reservoir_volume_std','reservoir_volume_total'};
    waterNew = { ...
        'number of open-water bodies','number of known reservoirs', ...
        'minimum open-water-body area','mean open-water-body area', ...
        'maximum open-water-body area','open-water-body area standard deviation', ...
        'total open-water area', ...
        'minimum open-water-body volume','mean open-water-body volume', ...
        'maximum open-water-body volume','open-water-body volume standard deviation', ...
        'total open-water volume', ...
        'minimum reservoir area','mean reservoir area','maximum reservoir area', ...
        'reservoir-area standard deviation','total reservoir area', ...
        'minimum reservoir volume','mean reservoir volume','maximum reservoir volume', ...
        'reservoir-volume standard deviation','total reservoir volume'};
    k = find(strcmp(waterOld,name),1);
    if ~isempty(k)
        txt = waterNew{k};
        return
    end

    % A few repeated nonmonthly summary names.
    simpleOld = { ...
        'daily_discharge_mean','daily_discharge_std', ...
        'runoff_ratio_mean','runoff_ratio_std', ...
        'streamflow_elasticity','fdc_slope_mean','fdc_slope_std', ...
        'bfi_mean','bfi_std','hfd_mean','hfd_std', ...
        'fracsnow1_mean','fracsnow1_std','fracsnow2_mean','fracsnow2_std'};
    simpleNew = { ...
        'mean daily discharge','daily discharge standard deviation', ...
        'mean runoff ratio','runoff-ratio standard deviation', ...
        'streamflow elasticity','mean flow-duration-curve slope', ...
        'flow-duration-curve slope standard deviation', ...
        'mean baseflow index','baseflow-index standard deviation', ...
        'mean half-flow date','half-flow-date standard deviation', ...
        'mean snow fraction','snow-fraction standard deviation', ...
        'mean snow fraction','snow-fraction standard deviation'};

    k = find(strcmp(simpleOld,name),1);
    if ~isempty(k)
        txt = simpleNew{k};
    end
end


% ==============================================
function txt = local_ca_ordinal_number(value)
% ==============================================
% Return an English ordinal number such as 1st, 5th, or 25th.

    value = round(value);
    lastTwo = mod(value,100);
    if lastTwo >= 11 && lastTwo <= 13
        suffix = 'th';
    else
        switch mod(value,10)
            case 1
                suffix = 'st';
            case 2
                suffix = 'nd';
            case 3
                suffix = 'rd';
            otherwise
                suffix = 'th';
        end
    end
    txt = sprintf('%d%s',value,suffix);
end


% =================================================
function txt = local_ca_attribute_description(name)
% =================================================
% Translate the repeated CAMELS-SPAT soil/geology naming convention.

    txt = char(name);

    % Depth interval: e.g., 60_100cm -> 60–100 cm.
    depth = regexp(txt,'_(\d+)_(\d+)cm_','tokens','once');
    depthText = '';
    if ~isempty(depth)
        depthText = sprintf(', %s–%s cm',depth{1},depth{2});
        txt = regexprep(txt,'_\d+_\d+cm_','_');
    end

    % Separate the property from the raster/product statistic and the
    % catchment aggregation statistic.
    stats = { ...
        '_uncertainty_harmonic_mean','uncertainty values','harmonic mean of'; ...
        '_uncertainty_mean',         'uncertainty values','mean of'; ...
        '_uncertainty_min',          'uncertainty values','minimum of'; ...
        '_uncertainty_max',          'uncertainty values','maximum of'; ...
        '_uncertainty_std',          'uncertainty values','standard deviation of'; ...
        '_mean_harmonic_mean',       'mean values',       'harmonic mean of'; ...
        '_mean_mean',                'mean values',       'mean of'; ...
        '_mean_min',                 'mean values',       'minimum of'; ...
        '_mean_max',                 'mean values',       'maximum of'; ...
        '_mean_std',                 'mean values',       'standard deviation of'; ...
        '_harmonic_mean',            '',                  'harmonic mean'; ...
        '_mean',                     '',                  'mean'; ...
        '_min',                      '',                  'minimum'; ...
        '_max',                      '',                  'maximum'; ...
        '_std',                      '',                  'standard deviation'};

    qualifier = '';
    for k = 1:size(stats,1)
        suffix = stats{k,1};
        if local_ends_with(txt,suffix)
            txt = txt(1:end-numel(suffix));
            if isempty(stats{k,2})
                qualifier = stats{k,3};
            else
                qualifier = sprintf('%s %s',stats{k,3},stats{k,2});
            end
            break
        end
    end

    % Common abbreviations used by SoilGrids and the hydrogeology layers.
    replacements = { ...
        'bdod','bulk density'; ...
        'cfvo','coarse-fragment content'; ...
        'clay','clay content'; ...
        'nitrogen','nitrogen content'; ...
        'ocd','organic-carbon density'; ...
        'ocs','organic-carbon stock'; ...
        'phh2o','soil pH'; ...
        'sand','sand content'; ...
        'silt','silt content'; ...
        'soc','soil organic-carbon content'; ...
        'cec','cation-exchange capacity'; ...
        'conductivity','hydraulic conductivity'; ...
        'log_permeability','log permeability'; ...
        'regolith_thickness','regolith thickness'; ...
        'soil_thickness','soil thickness'; ...
        'sedimentary_thickness','sedimentary thickness'; ...
        'average_thickness','average subsurface thickness'};

    property = strrep(txt,'_',' ');
    for k = 1:size(replacements,1)
        if strcmp(txt,replacements{k,1})
            property = replacements{k,2};
            break
        end
    end

    property(1) = upper(property(1));
    if isempty(qualifier)
        txt = [property depthText];
    else
        txt = sprintf('%s%s: %s',property,depthText,qualifier);
    end
end

% =====================================
function tf = local_ends_with(str,suffix)
% =====================================
    tf = numel(str) >= numel(suffix) ...
        && strcmp(str(end-numel(suffix)+1:end),suffix);
end

