% ================================
function ATTR = local_cl_catalog()
% ================================
% Order follows read_attr_CL using 1_CAMELScl_attributes.txt after
% transposing the CAMELS-Chile master table and retaining numeric fields.

    labels = { ...
        '[1] Gauge outlet latitude for basin location (°)'; ...
        '[2] Gauge outlet longitude for basin location (°)'; ...
        '[3] Number of daily streamflow observations in the record'; ...
        '[4] Catchment drainage area reported for the stream gauge (km²)'; ...
        '[5] Elevation of the stream gauge (a.m.s.l)'; ...
        '[6] Mean elevation (m)'; ...
        '[7] Median catchment elevation (a.m.s.l)'; ...
        '[8] Maximum elevation (m)'; ...
        '[9] Minimum elevation (m)'; ...
        '[10] Mean terrain slope across the contributing catchment'; ...
        '[11] Number of nested gauges inside the catchment'; ...
        '[12] Number of downstream catchments containing this gauge'; ...
        '[13] Fraction of catchment in the dominant geology class'; ...
        '[14] Fraction of catchment in the secondary geology class'; ...
        '[15] Fraction of catchment underlain by carbonate rocks'; ...
        '[16] Fraction of catchment area covered by cropland vegetation'; ...
        '[17] Fraction of catchment covered by native forest'; ...
        '[18] Fraction of catchment covered by forest plantation'; ...
        '[19] Fraction of catchment covered by grassland'; ...
        '[20] Fraction of catchment covered by shrubland'; ...
        '[21] Fraction of catchment area covered by wetland land'; ...
        '[22] Fraction of catchment covered by impervious surfaces'; ...
        '[23] Fraction of catchment classified as barren land cover'; ...
