        'runoff_ratio'; ...
        'stream_elas'; ...
        'slope_fdc'; ...
        'baseflow_index'; ...
        'hfd_mean'; ...
        'Q5'; ...
        'Q95'; ...
        'high_q_freq'; ...
        'high_q_dur'; ...
        'low_q_freq'; ...
        'low_q_dur'; ...
        'zero_q_freq' };

    ATTR.labels = labels;
    ATTR.names = names;
    ATTR.selectable = true(1,numel(labels));

    % Timing/string and streamflow-derived hydrologic attributes are not
    % default continuous predictors. Keep streamflow signatures out of the
    % default set to avoid leakage from observed discharge.
    bad = [16 19 92 93];

    ATTR.selectable(bad) = false;

    ATTR.default_ids = [ ...
        2 1 ...                 % location: latitude/longitude
        5 6 7 ...               % basin size/shape/elevation metadata
        12 13 14 15 ...         % precipitation/PET/aridity/snow climate
        17 18 20 21 22 ...      % precipitation extremes and seasonality
        25 27 28 29 30 ...      % topography/elevation/slope
        31 32 33 34 ...         % soil/texture/storage
        39 40 42 43 ...         % geology/permeability/bedrock
        44 45 46 47 48 ...      % land cover fractions
        49 50 51];              % human influence/storage/regulation

    ATTR.default_ids = ATTR.default_ids( ...
        ATTR.default_ids >= 1 ...
        & ATTR.default_ids <= numel(labels));

    ATTR.default_ids = setdiff( ...
        ATTR.default_ids,bad,'stable');

end

