        711 712 713 714 715 716 717 718 719 720 721 722 ...
        800 807 824 ];
    bad = bad(bad >= 1 ...
        & bad <= numel(labels));
    ATTR.selectable(bad) = false;

    ATTR.default_ids = [ ...
        32 ...                      % gauge elevation
        50 51 53 54 55 56 57 58 ... % drainage density and basin shape
        112 ...                     % median elevation
        213 ...                     % median distance to outlet
        314 ...                     % median topographic index
        415 ...                     % median slope
        733 734 735 736 737 ...     % CLC 2018 level-1 land-cover fractions
        871 879 880 ...             % karst, hydrogeologic perm/porosity
        881 882 885 893 ...         % geology fractions
        897 898 899 ];              % dams and human influence
    
    ATTR.default_ids = ATTR.default_ids( ...
        ATTR.default_ids >= 1 ...
        & ATTR.default_ids <= numel(labels));
    
    ATTR.default_ids = setdiff( ...
        ATTR.default_ids,bad,'stable');

end

