        'agricultural_land'; ...
        'urban' };

    ATTR.labels = labels;
    ATTR.names = names;
    ATTR.selectable = true(1,numel(labels));

    % Discharge-derived attributes are useful for diagnostics but should not
    % be default predictors because they use observed streamflow information.
    bad = [15 16];                  % Qspec_sum, runoff ratio
    ATTR.selectable(bad) = false;

    ATTR.default_ids = [ ...
        1 2 3 4 5 ...               % location, area, basin shape
        6 9 10 11 12 13 14 ...      % climate/PET/aridity information
        18 19 20 21 25 30 31 ...    % elevation, drainage position, slope
        35 36 40 41 ...             % wetness and terrain ruggedness
        42 43 44 45 46 47 48 ...    % geology and permeability
        49 50 51 52 53];            % land use

    ATTR.default_ids = ATTR.default_ids( ...
        ATTR.default_ids >= 1 ...
        & ATTR.default_ids <= numel(labels));

    ATTR.default_ids = setdiff( ...
        ATTR.default_ids,bad,'stable');

end

% ================================
function ATTR = local_nz_catalog()
% ================================
% Order follows read_attr_NZ after merging the CAMELS-NZ catchment
% information, climatic, land-cover, geology, and anthropogenic CSV files,
% then retaining numeric/logical fields only. Categorical descriptors such
% as climate zone, land cover, geology, flow regime, and influence are used
% for naming/zones but are not continuous SAGE predictors.

    labels = { ...
        '[1] Gauge latitude (°)'; ...
        '[2] Gauge longitude (°)'; ...
        '[3] Catchment drainage area (km²)'; ...
        '[4] Numeric region identifier'; ...
        '[5] Upstream lake area/fraction'; ...
        '[6] Lake indicator/fraction'; ...
        '[7] Stream order'; ...
        '[8] Mean elevation (m)'; ...
        '[9] Fraction of steep upstream terrain'; ...
        '[10] Fraction of low-gradient upstream terrain'; ...
        '[11] Mean upstream slope (°)'; ...
        '[12] Distance to sea (km)'; ...
        '[13] Number of record years'; ...
        '[14] Rain days above 25 mm'; ...
        '[15] Rain days above 10 mm'; ...
        '[16] Mean annual rainfall (mm)'; ...
        '[17] Annual rainfall variability'; ...
        '[18] Mean potential evapotranspiration (mm/day)'; ...
        '[19] Particle-size index'; ...
        '[20] Rock-hardness index'; ...
        '[21] Calcium/carbonate index'; ...
        '[22] Dam indicator'; ...
        '[23] Weir indicator'; ...
        '[24] Abstraction indicator'; ...
        '[25] Ephemeral-flow indicator'; ...
        '[26] Groundwater-influenced indicator'; ...
        '[27] Rating quality indicator'; ...
        '[28] Snow-influenced indicator'; ...
        '[29] Downstream dam affected indicator' };

    names = { ...
        'gauge_lat'; ...
        'gauge_lon'; ...
        'area'; ...
        'region_id'; ...
        'upstream_lakes'; ...
        'us_lake'; ...
        'stream_order'; ...
        'elev_mean'; ...
        'us_steep'; ...
        'us_lowgrad'; ...
        'us_aveslope'; ...
        'dist_sea'; ...
        'records'; ...
        'days_rain_gt25'; ...
        'rain_days_10'; ...
        'p_mean'; ...
        'p_var'; ...
        'pet_mean'; ...
        'particle_size'; ...
        'hardrock_index'; ...
        'carbonate_index'; ...
        'is_dam'; ...
        'is_weir'; ...
        'is_abstracted'; ...
        'is_ephemeral'; ...
        'is_gw_influenced'; ...
        'is_rating_ok'; ...
        'is_snow_influenced'; ...
        'ds_dam_affected' };

    ATTR.labels = labels;
    ATTR.names = names;
    ATTR.selectable = true(1,numel(labels));

    % Do not use identifiers/record length/quality fields as default
    % predictors. They remain visible only where useful for diagnostics.
    bad = [5 29];
    ATTR.selectable(bad) = false;

    % Compact default set: location, catchment size, topography, lake
    % influence, climate, geology, and major anthropogenic flags. No
    % streamflow-derived signatures are used as default predictors.
    ATTR.default_ids = [ ...
        1 2 3 ...               % location and area
        6 7 8 9 10 11 12 ...    % terrain, stream order, lake influence
        14 15 16 17 18 ...      % climate means and rainfall frequency
        19 20 21 ...            % geology indices
        22 23 24 25 26 28];     % anthropogenic and snow indicators

end

% ================================
function ATTR = local_za_catalog()
% ================================
% GRDC-Caravan South Africa. Reuse the curated HydroATLAS names and
% readable labels from South Korea because both releases use the same
% HydroATLAS schema. Monthly duplicates are available but not selected.

    coreNames = {'gauge_lat';'gauge_lon';'area';'p_mean'; ...
        'pet_mean_fao_pm';'aridity_fao_pm';'p_seasonality'; ...
        'frac_snow';'high_prec_freq';'high_prec_dur'; ...
        'low_prec_freq';'low_prec_dur'};
    coreLabels = {'Gauge latitude (degrees)'; ...
        'Gauge longitude (degrees)';'Catchment area (km^2)'; ...
        'Mean precipitation (mm/day)'; ...
        'Mean FAO Penman-Monteith potential evaporation (mm/day)'; ...
        'FAO Penman-Monteith aridity index'; ...
        'Precipitation seasonality'; ...
        'Fraction of precipitation falling as snow'; ...
        'High-precipitation frequency (days/year)'; ...
        'High-precipitation duration (days/event)'; ...
        'Low-precipitation frequency (days/year)'; ...
        'Low-precipitation duration (days/event)'};
    K = local_kr_catalog();
    hydroStart = find(strcmp(K.names,'dis_m3_pyr'),1);
    hydroEnd = find(strcmp(K.names,'hdi_ix_sav'),1);
    hydroNames=K.names(hydroStart:hydroEnd);
    hydroLabels=regexprep(K.labels(hydroStart:hydroEnd),'^\[\d+\]\s*','');
    hydroNames=regexprep(hydroNames,'_uav$','_sav');
    hydroNames=regexprep(hydroNames,'_use$','_sse');
    hydroNames=regexprep(hydroNames,'_u(\d\d)$','_s$1');
    hydroNames=regexprep(hydroNames,'_ug(\d)$','_sg$1');
    hydroNames=regexprep(hydroNames,'_u93$','_s93');
    hydroNames=regexprep(hydroNames,'_u09$','_s09');
    keep=~ismember(hydroNames,{'gad_id_smj','gdp_ud_usu'});
    hydroNames=hydroNames(keep); hydroLabels=hydroLabels(keep);
    hydroNames=[{'area_fraction_used_for_aggregation';'gdp_ud_sav'; ...
        'gdp_ud_ssu'}; hydroNames];
    hydroLabels=[{'Catchment-area fraction used for aggregation'; ...
        'Mean upstream gross domestic product from HydroATLAS (USD)'; ...
        'Total upstream gross domestic product from HydroATLAS (USD)'}; ...
        hydroLabels];
    ATTR.names = [coreNames; hydroNames];
    descriptions = [coreLabels; hydroLabels];
    ATTR.labels=cell(size(descriptions));
    for k=1:numel(descriptions), ATTR.labels{k}=sprintf('[%d] %s',k,descriptions{k}); end
    preferred = {'gauge_lat','gauge_lon','area','p_mean', ...
        'pet_mean_fao_pm','aridity_fao_pm','p_seasonality','frac_snow', ...
        'high_prec_freq','high_prec_dur','low_prec_freq','low_prec_dur', ...
        'ele_mt_sav','ele_mt_smn','ele_mt_smx','slp_dg_sav', ...
        'clz_cl_smj','tmp_dc_syr','pre_mm_syr','pet_mm_syr', ...
        'ari_ix_sav','snw_pc_syr','for_pc_sse','crp_pc_sse', ...
        'pst_pc_sse','cly_pc_sav','snd_pc_sav','soc_th_sav', ...
        'kar_pc_sse','lit_cl_smj'};
    [tf,loc] = ismember(preferred,ATTR.names);
    ATTR.default_ids = loc(tf);
    ATTR.disabled_ids = find(ismember(ATTR.names, ...
        {'dis_m3_pyr','dis_m3_pmn','dis_m3_pmx','run_mm_syr'}));
    ATTR.selectable=true(1,numel(ATTR.names));
    ATTR.selectable(ATTR.disabled_ids)=false;
end

% ================================
function ATTR = local_na_catalog()
% ================================
% Namibia uses the same GRDC-Caravan attribute schema as South Africa.
    ATTR=local_za_catalog();
end

function ATTR=local_ar_catalog(), ATTR=local_za_catalog(); end
function ATTR=local_be_catalog(), ATTR=local_za_catalog(); end
function ATTR=local_mx_catalog(), ATTR=local_za_catalog(); end
function ATTR=local_bull_catalog()
    base = local_za_catalog();
    coreNames = {'gauge_lat';'gauge_lon';'area';'p_mean'; ...
        'pet_mean';'aridity';'frac_snow';'moisture_index'; ...
        'seasonality';'high_prec_freq';'high_prec_dur'; ...
        'low_prec_freq';'low_prec_dur'};
    coreLabels = {'Gauge latitude (degrees)'; ...
        'Gauge longitude (degrees)';'Catchment area (km^2)'; ...
        'Mean precipitation (mm/day)'; ...
        'Mean potential evapotranspiration (mm/day)'; ...
        'Aridity index';'Fraction of precipitation falling as snow'; ...
        'Moisture index';'Precipitation seasonality'; ...
        'High-precipitation frequency (days/year)'; ...
        'High-precipitation duration (days/event)'; ...
        'Low-precipitation frequency (days/year)'; ...
        'Low-precipitation duration (days/event)'};
    hydroNames = base.names(13:end);
    hydroLabels = regexprep(base.labels(13:end),'^\[\d+\]\s*','');
    ATTR.names = [coreNames;hydroNames];
    descriptions = [coreLabels;hydroLabels];
    ATTR.labels = cell(size(descriptions));
    for i = 1:numel(descriptions)
        ATTR.labels{i} = sprintf('[%d] %s',i,descriptions{i});
    end
    preferred = {'gauge_lat','gauge_lon','area','p_mean', ...
        'pet_mean','aridity','moisture_index','seasonality','frac_snow', ...
        'high_prec_freq','high_prec_dur','low_prec_freq','low_prec_dur', ...
        'ele_mt_sav','ele_mt_smn','ele_mt_smx','slp_dg_sav', ...
        'clz_cl_smj','tmp_dc_syr','pre_mm_syr','pet_mm_syr', ...
        'snw_pc_syr','for_pc_sse','crp_pc_sse','pst_pc_sse', ...
        'cly_pc_sav','soc_th_sav','kar_pc_sse','lit_cl_smj'};
    preferred = [preferred, ...
        {'ire_pc_sse','rev_mc_usu','dor_pc_pva','pop_ct_usu', ...
        'nli_ix_sav','hft_ix_s09'}];
    [tf,loc] = ismember(preferred,ATTR.names);
    ATTR.default_ids = loc(tf);
    ATTR.disabled_ids = find(ismember(ATTR.names, ...
        {'dis_m3_pyr','dis_m3_pmn','dis_m3_pmx','run_mm_syr'}));
    ATTR.selectable = true(1,numel(ATTR.names));
    ATTR.selectable(ATTR.disabled_ids) = false;
end
function ATTR=local_ee_catalog(), ATTR=local_za_catalog(); end
function ATTR=local_ie_catalog(), ATTR=local_za_catalog(); end
function ATTR=local_jm_catalog(), ATTR=local_za_catalog(); end
function ATTR=local_no_catalog(), ATTR=local_za_catalog(); end
function ATTR=local_pr_catalog(), ATTR=local_za_catalog(); end

% ================================
function ATTR = local_jp_catalog()
% ================================
% HydroATLAS attributes supplied with MERV-Jp. Identifiers, names, outlet
% coordinates, QC fields, and runoff are not selectable model inputs.
% HydroATLAS values retain their published native encoding.

    names = { ...
        'area_merv_km2'; 'gwt_cm_sav'; 'ele_mt_sav'; ...
        'slp_dg_sav'; 'sgr_dk_sav'; 'tmp_dc_syr'; ...
        'pre_mm_syr'; 'pet_mm_syr'; 'aet_mm_syr'; ...
        'ari_ix_sav'; 'cmi_ix_syr'; 'snw_pc_syr'; ...
        'for_pc_sse'; 'crp_pc_sse'; 'pst_pc_sse'; ...
        'ire_pc_sse'; 'gla_pc_sse'; 'prm_pc_sse'; ...
        'pac_pc_sse'; 'cly_pc_sav'; 'slt_pc_sav'; ...
        'snd_pc_sav'; 'soc_th_sav'; 'kar_pc_sse'; ...
        'ero_kh_sav'; 'urb_pc_sse'; 'hft_ix_s09'};

    descriptions = { ...
        'MERV-Jp catchment area (km^2)'; ...
        'Mean groundwater-table depth (HydroATLAS native scale)'; ...
        'Mean catchment elevation (m)'; ...
        'Mean terrain slope (HydroATLAS native scale)'; ...
        'Mean stream gradient (HydroATLAS native scale)'; ...
        'Mean annual air temperature (HydroATLAS native scale)'; ...
        'Mean annual precipitation (mm/year)'; ...
        'Mean annual potential evapotranspiration (mm/year)'; ...
        'Mean annual actual evapotranspiration (mm/year)'; ...
        'Aridity index (HydroATLAS native scale)'; ...
        'Climate moisture index (HydroATLAS native scale)'; ...
        'Snow-cover fraction (HydroATLAS native scale)'; ...
        'Forest cover (%)'; 'Cropland cover (%)'; ...
        'Pasture cover (%)'; 'Irrigated area (%)'; ...
        'Glacier cover (%)'; 'Permafrost cover (%)'; ...
        'Protected-area cover (%)'; 'Mean clay content (%)'; ...
        'Mean silt content (%)'; 'Mean sand content (%)'; ...
        'Mean soil organic carbon (HydroATLAS native scale)'; ...
        'Karst area (%)'; ...
        'Mean soil erosion (HydroATLAS native scale)'; ...
        'Urban area (%)'; 'Human-footprint index'};

    shared = { ...
        'inu_pc_smn'; 'inu_pc_smx'; 'inu_pc_slt'; ...
        'ele_mt_smn'; 'ele_mt_smx'; ...
        'clz_cl_smj'; 'cls_cl_smj'; 'snw_pc_smx'; ...
        'glc_cl_smj'; 'pnv_cl_smj'; ...
        'tbi_cl_smj'; 'tec_cl_smj'; 'fmh_cl_smj'; ...
        'fec_cl_smj'; 'lit_cl_smj'; 'hdi_ix_sav'};
    prefixes = {'tmp_dc','pre_mm','pet_mm','aet_mm', ...
        'cmi_ix','snw_pc','swc_pc'};
    for i = 1:numel(prefixes)
        prefix = prefixes{i};
        for month = 1:12
            shared{end+1,1} = sprintf( ...
                '%s_s%02d',prefix,month); %#ok<AGROW>
        end
    end
    shared = unique(shared,'stable');

    korea = local_kr_catalog();
    use = ismember(korea.names,shared) ...
        & ~ismember(korea.names,names);
    sharedNames = korea.names(use);
    sharedLabels = korea.labels(use);
    for i = 1:numel(sharedLabels)
        sharedLabels{i} = regexprep(sharedLabels{i}, ...
            '^\[\d+\]\s*','');
    end

    names = [names(:);sharedNames(:)];
    descriptions = [descriptions(:);sharedLabels(:)];
    labels = cell(size(descriptions));
    for i = 1:numel(descriptions)
        labels{i} = sprintf('[%d] %s',i,descriptions{i});
    end
    ATTR.labels = labels;
    ATTR.names = names;
    ATTR.selectable = true(1,numel(names));

    defaultNames = { ...
        'area_merv_km2'; 'gwt_cm_sav'; ...
        'ele_mt_sav'; 'ele_mt_smn'; 'ele_mt_smx'; ...
        'slp_dg_sav'; 'sgr_dk_sav'; ...
        'tmp_dc_syr'; 'pre_mm_syr'; 'pet_mm_syr'; ...
        'aet_mm_syr'; 'ari_ix_sav'; 'cmi_ix_syr'; ...
        'snw_pc_syr'; 'clz_cl_smj'; 'cls_cl_smj'; ...
        'for_pc_sse'; 'crp_pc_sse'; 'pst_pc_sse'; ...
        'ire_pc_sse'; 'gla_pc_sse'; 'prm_pc_sse'; ...
        'pac_pc_sse'; 'glc_cl_smj'; ...
        'cly_pc_sav'; 'slt_pc_sav'; 'snd_pc_sav'; ...
        'soc_th_sav'; 'kar_pc_sse'; 'ero_kh_sav'; ...
        'urb_pc_sse'; 'hft_ix_s09'};
    [found,location] = ismember(defaultNames,names);
    if ~all(found)
        error('attr_catalog:JPDefaultMissing', ...
            'A MERV-Jp default attribute is missing.');
    end
    ATTR.default_ids = location;
end

% ================================
function ATTR = local_kr_catalog()
% ================================
% Complete CAMELSH-KR catalog. All 195 HydroATLAS fields are available;
% monthly duplicates are deliberately absent from the 30-field default.
% Direct discharge/runoff summaries are disabled to avoid target leakage.

    coreNames = { ...
        'gauge_lat'; 'gauge_lon'; 'area'; 'area_hydroatlas'; 'p_mean'; ...
        'aridity'; 'p_seasonality'; 'frac_snow'; 'high_prec_freq'; 'high_prec_dur'; ...
        'low_prec_freq'; 'low_prec_dur'; 'era5_p_mean'; 'era5_pet_mean'; 'era5_aridity'; ...
        'era5_p_seasonality'; 'era5_frac_snow'; 'era5_high_prec_freq'; 'era5_high_prec_dur'; 'era5_low_prec_freq'; ...
        'era5_low_prec_dur'
        };
    coreDescriptions = { ...
        'Gauge latitude (degrees)'; 'Gauge longitude (degrees)'; ...
        'Catchment area (km^2)'; 'Catchment area from HydroATLAS (km^2)'; ...
        'Mean observed precipitation (mm/day)'; ...
        'Observed-climate aridity index'; 'Observed precipitation seasonality'; ...
        'Observed fraction of precipitation falling as snow'; ...
        'Observed high-precipitation frequency (days/year)'; ...
        'Observed high-precipitation duration (days/event)'; ...
        'Observed low-precipitation frequency (days/year)'; ...
        'Observed low-precipitation duration (days/event)'; ...
        'Mean ERA5-Land precipitation (mm/day)'; ...
        'Mean ERA5-Land potential evaporation (mm/day)'; ...
        'ERA5-Land aridity index'; 'ERA5-Land precipitation seasonality'; ...
        'ERA5-Land fraction of precipitation falling as snow'; ...
        'ERA5-Land high-precipitation frequency (days/year)'; ...
        'ERA5-Land high-precipitation duration (days/event)'; ...
        'ERA5-Land low-precipitation frequency (days/year)'; ...
        'ERA5-Land low-precipitation duration (days/event)'};

    hydroNames = { ...
        'dis_m3_pyr'; 'dis_m3_pmn'; 'dis_m3_pmx'; 'run_mm_syr'; 'inu_pc_smn'; ...
        'inu_pc_smx'; 'inu_pc_slt'; 'lka_pc_use'; 'lkv_mc_usu'; 'rev_mc_usu'; ...
        'dor_pc_pva'; 'ria_ha_usu'; 'riv_tc_usu'; 'gwt_cm_sav'; 'ele_mt_sav'; ...
        'ele_mt_smn'; 'ele_mt_smx'; 'slp_dg_uav'; 'sgr_dk_sav'; 'clz_cl_smj'; ...
        'cls_cl_smj'; 'tmp_dc_syr'; 'tmp_dc_smn'; 'tmp_dc_smx'; 'tmp_dc_s01'; ...
        'tmp_dc_s02'; 'tmp_dc_s03'; 'tmp_dc_s04'; 'tmp_dc_s05'; 'tmp_dc_s06'; ...
        'tmp_dc_s07'; 'tmp_dc_s08'; 'tmp_dc_s09'; 'tmp_dc_s10'; 'tmp_dc_s11'; ...
        'tmp_dc_s12'; 'pre_mm_syr'; 'pre_mm_s01'; 'pre_mm_s02'; 'pre_mm_s03'; ...
        'pre_mm_s04'; 'pre_mm_s05'; 'pre_mm_s06'; 'pre_mm_s07'; 'pre_mm_s08'; ...
        'pre_mm_s09'; 'pre_mm_s10'; 'pre_mm_s11'; 'pre_mm_s12'; 'pet_mm_syr'; ...
        'pet_mm_s01'; 'pet_mm_s02'; 'pet_mm_s03'; 'pet_mm_s04'; 'pet_mm_s05'; ...
        'pet_mm_s06'; 'pet_mm_s07'; 'pet_mm_s08'; 'pet_mm_s09'; 'pet_mm_s10'; ...
        'pet_mm_s11'; 'pet_mm_s12'; 'aet_mm_syr'; 'aet_mm_s01'; 'aet_mm_s02'; ...
        'aet_mm_s03'; 'aet_mm_s04'; 'aet_mm_s05'; 'aet_mm_s06'; 'aet_mm_s07'; ...
        'aet_mm_s08'; 'aet_mm_s09'; 'aet_mm_s10'; 'aet_mm_s11'; 'aet_mm_s12'; ...
        'ari_ix_uav'; 'cmi_ix_syr'; 'cmi_ix_s01'; 'cmi_ix_s02'; 'cmi_ix_s03'; ...
        'cmi_ix_s04'; 'cmi_ix_s05'; 'cmi_ix_s06'; 'cmi_ix_s07'; 'cmi_ix_s08'; ...
        'cmi_ix_s09'; 'cmi_ix_s10'; 'cmi_ix_s11'; 'cmi_ix_s12'; 'snw_pc_syr'; ...
        'snw_pc_smx'; 'snw_pc_s01'; 'snw_pc_s02'; 'snw_pc_s03'; 'snw_pc_s04'; ...
        'snw_pc_s05'; 'snw_pc_s06'; 'snw_pc_s07'; 'snw_pc_s08'; 'snw_pc_s09'; ...
        'snw_pc_s10'; 'snw_pc_s11'; 'snw_pc_s12'; 'glc_cl_smj'; 'glc_pc_u01'; ...
        'glc_pc_u02'; 'glc_pc_u03'; 'glc_pc_u04'; 'glc_pc_u05'; 'glc_pc_u06'; ...
        'glc_pc_u07'; 'glc_pc_u08'; 'glc_pc_u09'; 'glc_pc_u10'; 'glc_pc_u11'; ...
        'glc_pc_u12'; 'glc_pc_u13'; 'glc_pc_u14'; 'glc_pc_u15'; 'glc_pc_u16'; ...
        'glc_pc_u17'; 'glc_pc_u18'; 'glc_pc_u19'; 'glc_pc_u20'; 'glc_pc_u21'; ...
        'glc_pc_u22'; 'pnv_cl_smj'; 'pnv_pc_u01'; 'pnv_pc_u02'; 'pnv_pc_u03'; ...
        'pnv_pc_u04'; 'pnv_pc_u05'; 'pnv_pc_u06'; 'pnv_pc_u07'; 'pnv_pc_u08'; ...
        'pnv_pc_u09'; 'pnv_pc_u10'; 'pnv_pc_u11'; 'pnv_pc_u12'; 'pnv_pc_u13'; ...
        'pnv_pc_u14'; 'pnv_pc_u15'; 'wet_cl_smj'; 'wet_pc_ug1'; 'wet_pc_ug2'; ...
        'wet_pc_u01'; 'wet_pc_u02'; 'wet_pc_u03'; 'wet_pc_u04'; 'wet_pc_u05'; ...
        'wet_pc_u06'; 'wet_pc_u07'; 'wet_pc_u08'; 'wet_pc_u09'; 'for_pc_use'; ...
        'crp_pc_use'; 'pst_pc_use'; 'ire_pc_use'; 'gla_pc_use'; 'prm_pc_use'; ...
        'pac_pc_use'; 'tbi_cl_smj'; 'tec_cl_smj'; 'fmh_cl_smj'; 'fec_cl_smj'; ...
        'cly_pc_uav'; 'slt_pc_uav'; 'snd_pc_uav'; 'soc_th_uav'; 'swc_pc_syr'; ...
        'swc_pc_s01'; 'swc_pc_s02'; 'swc_pc_s03'; 'swc_pc_s04'; 'swc_pc_s05'; ...
        'swc_pc_s06'; 'swc_pc_s07'; 'swc_pc_s08'; 'swc_pc_s09'; 'swc_pc_s10'; ...
        'swc_pc_s11'; 'swc_pc_s12'; 'lit_cl_smj'; 'kar_pc_use'; 'ero_kh_uav'; ...
        'pop_ct_usu'; 'ppd_pk_uav'; 'urb_pc_use'; 'nli_ix_uav'; 'rdd_mk_uav'; ...
        'hft_ix_u93'; 'hft_ix_u09'; 'gad_id_smj'; 'gdp_ud_usu'; 'hdi_ix_sav'
        };
    atlas = local_es_catalog();
    [tfAtlas,locAtlas] = ismember(hydroNames,atlas.names);
    hydroDescriptions = cell(size(hydroNames));
    for k = 1:numel(hydroNames)
        if tfAtlas(k)
            hydroDescriptions{k} = regexprep( ...
                atlas.labels{locAtlas(k)},'^\[\d+\]\s*','');
        else
            hydroDescriptions{k} = ...
                local_kr_hydroatlas_label(hydroNames{k});
        end
    end

    damNames = { ...
        'dam_vol_tot'; 'dam_vol_eff'; 'dam_vol_low'; 'dam_vol_flood'; 'dam_wl_flood'; ...
        'dam_wl_normal'; 'dam_wl_low'
        };
    damDescriptions = { ...
        'Total dam storage volume'; 'Effective dam storage volume'; ...
        'Low-water dam storage volume'; 'Flood-control dam storage volume'; ...
        'Dam flood water level (m)'; 'Dam normal water level (m)'; ...
        'Dam low water level (m)'};

    names = [coreNames; hydroNames; damNames];
    descriptions = [coreDescriptions; hydroDescriptions; damDescriptions];
    labels = cell(size(descriptions));
    for k = 1:numel(descriptions)
        labels{k} = sprintf('[%d] %s',k,descriptions{k});
    end
    ATTR.labels = labels;
    ATTR.names = names;
    ATTR.selectable = true(1,numel(names));
    leakNames = {'dis_m3_pyr','dis_m3_pmn', ...
        'dis_m3_pmx','run_mm_syr'};
    ATTR.selectable(ismember(names,leakNames)) = false;

    defaultNames = { ...
        'gauge_lat'; 'gauge_lon'; 'area'; 'p_mean'; 'aridity'; ...
        'p_seasonality'; 'frac_snow'; 'high_prec_freq'; 'high_prec_dur'; 'low_prec_freq'; ...
        'low_prec_dur'; 'ele_mt_sav'; 'ele_mt_smn'; 'ele_mt_smx'; 'slp_dg_uav'; ...
        'clz_cl_smj'; 'tmp_dc_syr'; 'pre_mm_syr'; 'pet_mm_syr'; 'ari_ix_uav'; ...
        'cmi_ix_syr'; 'snw_pc_syr'; 'glc_cl_smj'; 'for_pc_use'; 'crp_pc_use'; ...
        'pst_pc_use'; 'cly_pc_uav'; 'snd_pc_uav'; 'soc_th_uav'; 'lit_cl_smj'
        };
    [tfDefault,locDefault] = ismember(defaultNames,names);
    if ~all(tfDefault)
        error('attr_catalog:KRDefaultMissing', ...
            'A CAMELSH-KR default attribute is missing.');
    end
    ATTR.default_ids = locDefault;
end

% ================================
function label = local_kr_hydroatlas_label(name)
% Labels absent from the older Spain HydroATLAS subset.
    token = regexp(name,'^glc_pc_u(\d\d)$','tokens','once');
    if ~isempty(token)
        label = sprintf(['Global land-cover class %d fraction ' ...
            'from HydroATLAS (%%)'],str2double(token{1}));
        return
    end
    token = regexp(name,'^pnv_pc_u(\d\d)$','tokens','once');
    if ~isempty(token)
        label = sprintf(['Potential natural vegetation class %d fraction ' ...
            'from HydroATLAS (%%)'],str2double(token{1}));
        return
    end
    token = regexp(name,'^wet_pc_u(\d\d)$','tokens','once');
    if ~isempty(token)
        label = sprintf(['Wetland class %d fraction ' ...
            'from HydroATLAS (%%)'],str2double(token{1}));
        return
    end

    keys = {'lka_pc_use','slp_dg_uav','ari_ix_uav', ...
        'wet_pc_ug1','wet_pc_ug2','for_pc_use','crp_pc_use', ...
        'pst_pc_use','ire_pc_use','gla_pc_use','prm_pc_use', ...
        'pac_pc_use','cly_pc_uav','slt_pc_uav','snd_pc_uav', ...
        'soc_th_uav','kar_pc_use','ero_kh_uav','ppd_pk_uav', ...
        'urb_pc_use','nli_ix_uav','rdd_mk_uav','hft_ix_u93', ...
        'hft_ix_u09','gad_id_smj','gdp_ud_usu'};
    values = {'Lake-area fraction from HydroATLAS (%)', ...
        'Mean catchment slope from HydroATLAS (degrees)', ...
        'Climatic aridity index from HydroATLAS', ...
        'Global wetland class 1 fraction from HydroATLAS (%)', ...
        'Global wetland class 2 fraction from HydroATLAS (%)', ...
        'Forest-cover fraction from HydroATLAS (%)', ...
        'Cropland fraction from HydroATLAS (%)', ...
        'Pasture fraction from HydroATLAS (%)', ...
        'Irrigated-area fraction from HydroATLAS (%)', ...
        'Glacier-area fraction from HydroATLAS (%)', ...
        'Permafrost-area fraction from HydroATLAS (%)', ...
        'Protected-area fraction from HydroATLAS (%)', ...
        'Mean clay fraction from HydroATLAS (%)', ...
        'Mean silt fraction from HydroATLAS (%)', ...
        'Mean sand fraction from HydroATLAS (%)', ...
        'Mean soil organic-carbon content from HydroATLAS (tonnes/ha)', ...
        'Karst-area fraction from HydroATLAS (%)', ...
        'Mean soil-erosion potential from HydroATLAS (kg/ha/year)', ...
        'Mean population density from HydroATLAS (people/km^2)', ...
        'Urban-area fraction from HydroATLAS (%)', ...
        'Mean night-time-lights index from HydroATLAS', ...
        'Mean road density from HydroATLAS (m/km^2)', ...
        'Human-footprint index around 1993 from HydroATLAS', ...
        'Human-footprint index around 2009 from HydroATLAS', ...
        'Dominant administrative-area identifier from HydroATLAS', ...
        'Upstream gross domestic product from HydroATLAS (USD)'};
    ix = find(strcmp(name,keys),1);
    if isempty(ix)
        % A new source field must never block basin preparation merely
        % because its display label has not yet been curated.
        label = ['HydroATLAS: ' strrep(name,'_',' ')];
        return
    end
    label = values{ix};
end

% ================================
function ATTR = local_kr_catalog_legacy()
% ================================
% Curated, non-streamflow CAMELSH-KR predictors. The climate variables
% without a prefix are observation-based; ERA5-Land counterparts carry an
% era5_ prefix. HydroATLAS variables are limited to physiographic and
% climatic predictors so discharge-derived signatures cannot leak into
% model training.

    names = { ...
        'gauge_lat'; 'gauge_lon'; 'area'; 'area_hydroatlas'; ...
        'p_mean'; 'aridity'; 'p_seasonality'; 'frac_snow'; ...
        'high_prec_freq'; 'high_prec_dur'; ...
        'low_prec_freq'; 'low_prec_dur'; ...
        'era5_p_mean'; 'era5_pet_mean'; 'era5_aridity'; ...
