        'dam_vol_tot'; 'dam_vol_eff'; 'dam_vol_low'; ...
        'dam_vol_flood'; 'dam_wl_flood'; ...
        'dam_wl_normal'; 'dam_wl_low'};

    labels = { ...
        '[1] Gauge latitude (°)'; ...
        '[2] Gauge longitude (°)'; ...
        '[3] Catchment area (km²)'; ...
        '[4] Catchment area from HydroATLAS (km²)'; ...
        '[5] Mean observed precipitation (mm/day)'; ...
