        '[20] ERA5-Land low-precipitation frequency (days/year)'; ...
        '[21] ERA5-Land low-precipitation duration (days/event)'; ...
        '[22] Mean catchment elevation from HydroATLAS (m)'; ...
        '[23] Mean annual precipitation from HydroATLAS (mm/year)'; ...
        '[24] Mean annual potential evapotranspiration from HydroATLAS (mm/year)'; ...
        '[25] Aridity index from HydroATLAS'; ...
        '[26] Mean annual air temperature from HydroATLAS (0.1 °C)'; ...
        '[27] Mean annual snow-cover extent from HydroATLAS (%)'; ...
        '[28] Forest cover from HydroATLAS (%)'; ...
        '[29] Cropland cover from HydroATLAS (%)'; ...
        '[30] Pasture cover from HydroATLAS (%)'; ...
        '[31] Irrigated-area fraction from HydroATLAS (%)'; ...
        '[32] Urban-area fraction from HydroATLAS (%)'; ...
        '[33] Lake-area fraction from HydroATLAS (%)'; ...
        '[34] Mean groundwater-table depth from HydroATLAS (cm)'; ...
        '[35] Upstream reservoir volume from HydroATLAS (million m³)'; ...
        '[36] Degree of flow regulation from HydroATLAS (%)'; ...
        '[37] Total dam storage volume'; ...
        '[38] Effective dam storage volume'; ...
        '[39] Low-water dam storage volume'; ...
        '[40] Flood-control dam storage volume'; ...
        '[41] Dam flood water level (m)'; ...
