% ================================
function ATTR = local_is_catalog()
% ================================
% Gauge attributes first, followed by numeric catchment attributes.
    labels = { ...
        '[1] Gauge latitude (°)'; ...
        '[2] Gauge longitude (°)'; ...
        '[3] Gauge elevation (m)'; ...
        '[4] Catchment area (km²)'; ...
        '[5] Mean catchment elevation (m)'; ...
        '[6] Median catchment elevation (m)'; ...
        '[7] Catchment elevation range (m)'; ...
        '[8] Catchment elevation standard deviation (m)'; ...
        '[9] Mean catchment slope'; ...
        '[10] Mean vertical distance'; ...
        '[11] Mean vertical angle'; ...
        '[12] Mean catchment aspect'; ...
        '[13] Catchment elongation ratio'; ...
        '[14] Stream density'; ...
        '[15] Mean annual precipitation'; ...
        '[16] Mean reference evapotranspiration'; ...
        '[17] Aridity index'; ...
        '[18] Precipitation seasonality'; ...
        '[19] Snow precipitation fraction'; ...
        '[20] High-precipitation frequency'; ...
        '[21] Mean high-precipitation duration'; ...
        '[22] Low-precipitation frequency'; ...
        '[23] Mean low-precipitation duration'; ...
        '[24] Mean discharge'; ...
        '[25] Runoff ratio'; ...
        '[26] Mean half-flow date'; ...
        '[27] Flow-duration-curve slope'; ...
        '[28] Baseflow index (Ladson method)'; ...
        '[29] Streamflow elasticity'; ...
        '[30] High-flow frequency'; ...
        '[31] Mean high-flow duration'; ...
        '[32] 95th-percentile flow quantile (Q95)'; ...
        '[33] Low-flow frequency'; ...
        '[34] Mean low-flow duration'; ...
        '[35] 5th-percentile flow quantile (Q5)'; ...
        '[36] Agricultural land fraction'; ...
        '[37] Bare-land fraction'; ...
        '[38] Forest fraction'; ...
        '[39] Glacier fraction'; ...
        '[40] Lake fraction'; ...
        '[41] Urban fraction'; ...
        '[42] Scrubland fraction'; ...
        '[43] Wetland fraction'; ...
        '[44] Maximum leaf area index'; ...
        '[45] Seasonal leaf area index difference'; ...
        '[46] Maximum normalized difference vegetation index'; ...
        '[47] Minimum normalized difference vegetation index'; ...
        '[48] Maximum green vegetation fraction'; ...
        '[49] Seasonal green vegetation fraction difference'; ...
        '[50] Depth to bedrock'; ...
        '[51] Rooting depth'; ...
        '[52] Soil porosity'; ...
        '[53] Soil total available water capacity'; ...
        '[54] Soil sand fraction'; ...
        '[55] Soil silt fraction'; ...
        '[56] Soil clay fraction'; ...
        '[57] Soil gravel fraction'; ...
        '[58] Soil organic carbon fraction'; ...
        '[59] Glacier-covered fraction'; ...
        '[60] Glacier area'; ...
        '[61] Mean glacier elevation (m)'; ...
        '[62] Minimum glacier elevation (m)'; ...
        '[63] Maximum glacier elevation (m)'; ...
        '[64] Mean glacier aspect'; ...
        '[65] Mean glacier slope'; ...
        '[66] Glacier fraction with slope below 20°'; ...
        '[67] Glacier centroid longitude (°)'; ...
        '[68] Glacier centroid latitude (°)' };

    names = {'gauge_lat';'gauge_lon';'elevation';'area_calc'; ...
        'elev_mean';'elev_med';'elev_ran';'elev_std';'slope_mean'; ...
        'mvert_dist';'mvert_ang';'asp_mean';'elon_ratio';'strm_dens'; ...
        'p_mean';'ref_et_mean';'aridity';'p_season';'frac_snow'; ...
        'high_prec_fr';'high_prec_du';'lo_prec_fr';'low_prec_du'; ...
        'q_mean';'runoff_ratio';'hfd_mean';'slope_fdc'; ...
        'baseflow_index_ladson';'stream_elas';'high_q_freq'; ...
        'high_q_dur';'Q95';'low_q_freq';'low_q_dur';'Q5'; ...
        'agr_fra';'bare_fra';'forest_fra';'glac_fra';'lake_fra'; ...
        'urban_fra';'scrub_fra';'wetl_fra';'lai_max';'lai_diff'; ...
        'ndvi_max';'ndvi_min';'gvf_max';'gvf_diff';'bedrk_dep'; ...
        'root_dep';'soil_poros';'soil_tawc';'sand_fra';'silt_fra'; ...
        'clay_fra';'grav_fra';'oc_fra';'g_frac';'g_area'; ...
        'g_mean_el';'g_min_el';'g_max_el';'g_aspect';'g_slope'; ...
        'g_slopel20';'g_lon';'g_lat'};
    ATTR.labels=labels;
    ATTR.names=names;
    ATTR.selectable=true(1,numel(names));

    % Discharge-derived hydrologic signatures are incomplete for many
    % LamaH-Ice basins and must not be used as SAGE predictors. Excluding
    % them also prevents observed-flow information from leaking into the
    % catchment-attribute-to-parameter mapping.
    badHydro = 24:35;
    ATTR.selectable(badHydro) = false;

    % Glacier geometry/location attributes are defined only for catchments
    % containing glaciers and therefore contain NaN values elsewhere.
    badGlacierSpecific = 61:68;
    ATTR.selectable(badGlacierSpecific) = false;

    % Default predictors contain only finite, basin-wide physiographic,
    % climatic, land-cover, vegetation, and soil attributes.
    ATTR.default_ids = [1:19 36:48 50:56];
end

