% ===================================
function ATTR = local_mach_catalog()
% ===================================
% MACH defaults intentionally exclude discharge-derived signatures and
% source variables that are incomplete across the 1,014-basin universe.

    names = { ...
        'gauge_lat'; 'gauge_lon'; 'area'; 'alt_meters'; ...
        'basin_slope'; 'elev_mean'; 'elev_min'; 'elev_max'; ...
        'p_mean'; 'pet_mean'; 'TAV9120'; 'TMIN9120'; 'TMAX9120'; ...
        'AET9120'; 'TN10p'; 'TN90p'; 'TX10p'; 'TX90p'; ...
        'TOT_SANDAVE'; 'TOT_SILTAVE'; 'TOT_CLAYAVE'; ...
        'TOT_OM'; 'TOT_PERMAVE'; 'TOT_ROCKDEP'; 'TOT_BDAVE'; ...
        'TOT_AWCAVE'; 'TOT_pH'; 'CARB'; 'TOT_STREAM_SLOPE'; ...
        'TOT_STRM_DENS'; 'SINU'; 'TOT_TWI'; 'dam_count'; ...
        'TOT_POPDENS10'; 'TOT_FRESHWATER_WD'; ...
        'TOT_TOTAL_ROAD_DENS'};
    descriptions = { ...
        'Gauge latitude (deg)'; 'Gauge longitude (deg)'; ...
        'Basin area (km2)'; 'Gauge elevation (m)'; ...
        'Mean basin slope (%)'; 'Mean basin elevation (m)'; ...
        'Minimum basin elevation (m)'; ...
        'Maximum basin elevation (m)'; ...
        'Mean annual precipitation, 1991-2020 (mm/yr)'; ...
        'Mean annual PET, 1991-2020 (mm/yr)'; ...
        'Mean temperature, 1991-2020 (degC)'; ...
        'Mean minimum temperature, 1991-2020 (degC)'; ...
        'Mean maximum temperature, 1991-2020 (degC)'; ...
        'Mean annual actual ET, 1991-2020 (mm/yr)'; ...
        'Cold-night frequency (%)'; 'Warm-night frequency (%)'; ...
        'Cold-day frequency (%)'; 'Warm-day frequency (%)'; ...
        'Sand fraction (%)'; 'Silt fraction (%)'; ...
        'Clay fraction (%)'; 'Soil organic matter (%)'; ...
        'Soil permeability'; 'Depth to bedrock'; ...
        'Soil bulk density'; 'Available water capacity'; ...
        'Soil pH'; 'Carbonate-rock fraction (%)'; ...
        'Mean stream slope'; 'Stream density'; ...
        'Sinuosity'; 'Topographic wetness index'; ...
        'Number of dams'; 'Population density (persons/km2)'; ...
        'Freshwater withdrawals'; 'Road density (km/km2)'};
    labels = cell(size(names));
    for i = 1:numel(names)
        labels{i} = sprintf('[%d] %s',i,descriptions{i});
    end
    ATTR.labels = labels;
    ATTR.names = names;
    ATTR.selectable = true(1,numel(names));
    incomplete = [10 14 28 33];
    ATTR.default_ids = setdiff( ...
        1:numel(names),incomplete,'stable');
end

% =================================
function ATTR = local_ush_catalog()
% =================================
% CAMELSH-US: curated GAGES-II and NLDAS-2 attributes.
% Discharge-derived signatures are exposed as optional expert predictors
% but are never selected by default. Flow-record descriptors,
% annual/monthly climate duplicates and riparian duplicates are omitted.

    names = { ...
      'p_mean','pet_mean','aridity_index','p_seasonality','frac_snow', ...
      'high_prec_freq','high_prec_dur','low_prec_freq','low_prec_dur', ...
      'gauge_lat','gauge_lon','area','BAS_COMPACTNESS','LAT_CENT','LONG_CENT', ...
      'ELEV_MEAN_M_BASIN','ELEV_MAX_M_BASIN','ELEV_MIN_M_BASIN', ...
      'ELEV_MEDIAN_M_BASIN','ELEV_STD_M_BASIN','RRMEAN','RRMEDIAN', ...
      'SLOPE_PCT','ASPECT_DEGREES','ASPECT_NORTHNESS','ASPECT_EASTNESS', ...
      'GEOL_REEDBUSH_DOM_PCT','GEOL_HUNT_DOM_PCT', ...
      'AWCAVE','PERMAVE','BDAVE','OMAVE','WTDEPAVE','ROCKDEPAVE', ...
      'CLAYAVE','SILTAVE','SANDAVE','KFACT_UP','RFACT', ...
      'DEVNLCD06','FORESTNLCD06','PLANTNLCD06','WATERNLCD06','SNOWICENLCD06', ...
      'BARRENNLCD06','DECIDNLCD06','EVERGRNLCD06','MIXEDFORNLCD06', ...
      'SHRUBNLCD06','GRASSNLCD06','PASTURENLCD06','CROPSNLCD06', ...
      'WOODYWETNLCD06','EMERGWETNLCD06', ...
      'NDAMS_2009','DDENS_2009','STOR_NID_2009','STOR_NOR_2009', ...
      'CANALS_PCT','NPDES_MAJ_DENS','FRESHW_WITHDRAWAL','MINING92_PCT', ...
      'PCT_IRRIG_AG','PDEN_2000_BLOCK','ROADS_KM_SQ_KM','IMPNLCD06', ...
      'PADCAT1_PCT_BASIN','PADCAT2_PCT_BASIN','PADCAT3_PCT_BASIN', ...
      'T_AVG_BASIN','T_MAX_BASIN','T_MAXSTD_BASIN','T_MIN_BASIN', ...
      'T_MINSTD_BASIN','RH_BASIN','FST32F_BASIN','LST32F_BASIN', ...
      'WD_BASIN','WDMAX_BASIN', ...
      'HGA','HGB','HGC','HGD','HGVAR','NO4AVE','NO200AVE','NO10AVE', ...
      'STREAMS_KM_SQ_KM','STRAHLER_MAX','MAINSTEM_SINUOUSITY', ...
      'ARTIFPATH_PCT','HIRES_LENTIC_PCT','PCT_1ST_ORDER', ...
      'PCT_2ND_ORDER','PCT_6TH_ORDER_OR_MORE', ...
      'FRAGUN_BASIN','HIRES_LENTIC_NUM','HIRES_LENTIC_DENS', ...
      'HIRES_LENTIC_MEANSIZ','MAJ_NDAMS_2009','MAJ_DDENS_2009', ...
      'POWER_SUM_MW','NITR_APP_KG_SQKM','PHOS_APP_KG_SQKM', ...
      'PESTAPP_KG_SQKM','BFI_AVE','RUNAVE7100','WB5100_ANN_MM', ...
      'dis_m3_pyr','dis_m3_pmn','dis_m3_pmx','run_mm_syr'};

    desc = { ...
      'Mean precipitation (mm/day)','Mean potential evaporation (mm/day)', ...
      'Aridity index','Precipitation seasonality', ...
      'Fraction of precipitation falling as snow', ...
      'High-precipitation frequency (days/year)', ...
      'High-precipitation duration (days/event)', ...
      'Low-precipitation frequency (days/year)', ...
      'Low-precipitation duration (days/event)', ...
      'Gauge latitude (degrees)','Gauge longitude (degrees)', ...
      'Drainage area (km^2)','Basin compactness', ...
      'Basin-centroid latitude (degrees)','Basin-centroid longitude (degrees)', ...
      'Mean basin elevation (m)','Maximum basin elevation (m)', ...
      'Minimum basin elevation (m)','Median basin elevation (m)', ...
      'Elevation standard deviation (m)','Mean relief ratio', ...
      'Median relief ratio','Mean basin slope (%)','Mean aspect (degrees)', ...
      'Aspect northness','Aspect eastness', ...
      'Dominant Reed-Bush geology fraction (%)','Dominant Hunt geology fraction (%)', ...
      'Available water capacity','Soil permeability', ...
      'Soil bulk density','Soil organic matter','Water-table depth', ...
      'Depth to rock','Clay fraction','Silt fraction','Sand fraction', ...
      'Soil erodibility K factor','Rainfall erosivity R factor', ...
      'Developed land fraction','Forest fraction','Planted land fraction', ...
      'Open-water fraction','Snow and ice fraction','Barren land fraction', ...
      'Deciduous forest fraction','Evergreen forest fraction', ...
      'Mixed-forest fraction','Shrubland fraction','Grassland fraction', ...
      'Pasture fraction','Crop fraction','Woody-wetland fraction', ...
      'Emergent-wetland fraction','Number of dams','Dam density', ...
      'National Inventory of Dams storage','Normal dam storage', ...
      'Canal-affected fraction','Major discharge-permit density', ...
      'Freshwater withdrawal','Mining fraction','Irrigated-agriculture fraction', ...
      'Population density','Road density','Impervious fraction', ...
      'Protected-area category 1 fraction','Protected-area category 2 fraction', ...
      'Protected-area category 3 fraction', ...
      'Mean basin air temperature','Mean maximum basin air temperature', ...
      'Maximum-temperature variability','Mean minimum basin air temperature', ...
      'Minimum-temperature variability','Mean basin relative humidity', ...
      'First annual freezing date','Last annual freezing date', ...
      'Wet-day frequency','Maximum wet-day measure', ...
      'Hydrologic soil group A fraction','Hydrologic soil group B fraction', ...
      'Hydrologic soil group C fraction','Hydrologic soil group D fraction', ...
      'Hydrologic soil-group variability','Soil fraction finer than 4 mm', ...
      'Soil fraction finer than 200 micrometers', ...
      'Soil fraction finer than 10 micrometers', ...
      'Stream density (km/km^2)','Maximum Strahler stream order', ...
      'Main-stem sinuosity','Artificial flow-path fraction', ...
      'Lake and pond fraction','First-order stream fraction', ...
      'Second-order stream fraction','Sixth-or-higher-order stream fraction', ...
      'Undeveloped-land fragmentation','Number of lakes and ponds', ...
      'Lake and pond density','Mean lake and pond size', ...
      'Number of major dams','Major-dam density', ...
      'Installed power-generation capacity (MW)', ...
      'Nitrogen application (kg/km^2)','Phosphorus application (kg/km^2)', ...
      'Pesticide application (kg/km^2)', ...
      'Baseflow index (discharge-derived)', ...
      'Mean annual runoff, 1971--2000 (discharge-derived)', ...
      'Mean annual water-balance runoff, 1951--2000 (discharge-derived)', ...
      'Mean annual discharge (m^3/s; discharge-derived)', ...
      'Minimum monthly discharge (m^3/s; discharge-derived)', ...
      'Maximum monthly discharge (m^3/s; discharge-derived)', ...
      'Mean annual runoff depth (mm/year; discharge-derived)'};

    if numel(names) ~= numel(desc)
        error('attr_catalog:USHLabelCount', ...
            'CAMELSH-US attribute names and labels do not match.');
    end

    ATTR.names = names(:);
    ATTR.labels = cell(numel(names),1);
    for k = 1:numel(names)
        ATTR.labels{k} = sprintf('[%d] %s',k,desc{k});
    end
    ATTR.selectable = true(1,numel(names));

    % Default predictors are deliberately free of discharge-derived
    % quantities. The expanded specialist variables remain opt-in.
    ATTR.default_ids = [1:9 12 13 16:20 23 29:38 41 42 52 55];
end
